import React, { useEffect, useState } from "react";
import axios from "axios";
import AppShell from "./ui/AppShell";
import Panel from "./ui/Panel";
import StatCard from "./ui/StatCard";
import AlertBox from "./AlertBox";
import { FaClipboardList, FaUpload, FaBook } from "react-icons/fa";
import "./theme.css";

function AssignmentsStudent() {
  const studentId = localStorage.getItem("user_id");

  const [courses, setCourses] = useState([]);
  const [assignments, setAssignments] = useState([]);
  const [files, setFiles] = useState({});
  const [selectedCourse, setSelectedCourse] = useState("");
  const [alert, setAlert] = useState(null);

  useEffect(() => {
    loadCourses();
  }, []);

  const loadCourses = async () => {
    const coursesRes = await axios.get("http://127.0.0.1:8000/courses");
    const enrollRes = await axios.get(`http://127.0.0.1:8000/enrollments/${studentId}`);

    const enrolledIds = enrollRes.data.map((e) => e.course_id);

    setCourses(
      (coursesRes.data.courses || []).filter((c) => enrolledIds.includes(c.id))
    );
  };

  const loadAssignments = async (courseId) => {
    const res = await axios.get(`http://127.0.0.1:8000/assignments/${courseId}`);
    setAssignments(res.data.assignments || []);
  };

  const handleSubmit = async (assignmentId) => {
    try {
      const file = files[assignmentId];

      if (!file) {
        setAlert({ message: "Select file first", type: "error" });
        return;
      }

      const formData = new FormData();
      formData.append("assignment_id", assignmentId);
      formData.append("student_id", studentId);
      formData.append("file", file);

      const res = await axios.post(
        "http://127.0.0.1:8000/submit-assignment",
        formData,
        {
          headers: {
            "Content-Type": "multipart/form-data"
          }
        }
      );

      setAlert({ message: res.data.message, type: "success" });
      window.dispatchEvent(new Event("plannerUpdated"));
    } catch (err) {
      console.error(err);
      setAlert({ message: "Submission failed", type: "error" });
    }
  };

  return (
    <AppShell
      title="Assignments"
      subtitle="Upload your answer files as PDF or image for enrolled subjects."
    >
      {alert && <AlertBox message={alert.message} type={alert.type} onClose={() => setAlert(null)} />}

      <div className="page-grid-3" style={{ marginBottom: "20px" }}>
        <StatCard icon={<FaBook />} label="Courses" value={courses.length} hint="Courses you're enrolled in" />
        <StatCard icon={<FaClipboardList />} label="Assignments" value={assignments.length} hint="Assignments in selected course" />
        <StatCard icon={<FaUpload />} label="Submission Mode" value="Active" hint="Upload PDF/image responses" />
      </div>

      <Panel title="Select Course">
        <select
          className="select"
          value={selectedCourse}
          onChange={(e) => {
            setSelectedCourse(e.target.value);
            if (e.target.value) loadAssignments(e.target.value);
          }}
        >
          <option value="">Select Course</option>
          {courses.map((c) => (
            <option key={c.id} value={c.id}>
              {c.title}
            </option>
          ))}
        </select>
      </Panel>

      <div style={{ marginTop: "18px" }}>
        <Panel title="Assignments">
          {assignments.length === 0 ? (
            <p className="muted">No assignments found for this course.</p>
          ) : (
            assignments.map((a) => (
              <div className="list-card" key={a.id}>
                <h4 style={{ marginTop: 0 }}>{a.title}</h4>
                <div className="muted">{a.description}</div>
                <div className="muted" style={{ marginTop: "8px" }}>
                  Due: {a.due_date}
                </div>

                <input
                  type="file"
                  style={{ marginTop: "12px", marginBottom: "12px", color: "var(--text)" }}
                  onChange={(e) =>
                    setFiles({ ...files, [a.id]: e.target.files[0] })
                  }
                />

                <button className="btn btn-primary" onClick={() => handleSubmit(a.id)}>
                  Upload Answer
                </button>
              </div>
            ))
          )}
        </Panel>
      </div>
    </AppShell>
  );
}

export default AssignmentsStudent;
